fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let phase: i32 = t % 80;
    let mut r: i32 = 10 + phase;
    if phase > 40 { r = 10 + 80 - phase; }
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    host::display::clear(0x000010);
    let mut dy: i32 = 0 - r;
    while dy <= r {
        let mut dx: i32 = 0 - r;
        while dx <= r {
            if dx * dx + dy * dy <= r * r {
                host::display::set_pixel(cx + dx, cy + dy, 0x00ccff);
            }
            dx = dx + 1;
        }
        dy = dy + 1;
    }
    host::display::present();
}
